#include <iostream>
#include <iomanip>

int main() {
    // Demonstrate reading a stream of numbers safely without eof() pitfalls
    double value = 0.0;
    double total = 0.0;
    int count = 0;

    std::cout << std::fixed << std::setprecision(2);

    // Idiomatic C++ stream read: tests extraction success directly
    while (std::cin >> value) {
        total += value;
        count++;
    }

    std::cout << "Total items read: " << count << "\n";
    std::cout << "Calculated total: " << total << "\n";
    return 0;
}
